  "assets/palettes/main.palette.json": "{\n  \"format\": \"clementina-palette\",\n  \"version\": 1,\n  \"id\": \"palette:main\",\n  \"name\": \"Main\",\n  \"colors\": [0, 65535, 63488, 2016, 31, 65504, 63519, 2047]\n}\n",
  "checks/smoke.json": "{\n  \"settleCycles\": 3000000,\n  \"beforeText\": \"HELLO FROM ASSEMBLY\",\n  \"input\": \"A\",\n  \"afterText\": \"YOU PRESSED A\"\n}\n",
  "clementina.yaml": "format: clementina-project\nversion: 1\nname: My Game\ntarget:\n  machine: clementina-6502\nprogram:\n  entry: src/main.cbas\nassets:\n  palettes:\n    - assets/palettes/main.palette.json\n  paletteConfigs:\n    - assets/palette-configs/main.palette-config.json\n  tilesets: []\n  backgrounds: []\n  overlays: []\n  shapes: []\n  animations: []\nbuild:\n  outputDirectory: build\n  basic:\n    outputName: game\n    memoryTop: 28672 # $7000: BASIC stays below the assembly code\n  assembly:\n    sources:\n      - src/hello.s\n    linkerConfig: link.cfg\n    outputName: code\n    loadAddress: 28672 # $7000\n    entrySymbol: hello\n  video:\n    paletteConfigId: palette-config:main\n",
  "link.cfg": "MEMORY {\n  ZP: start=$98, size=$48, type=rw;\n  RAM: start=$7000, size=$1000, type=rw, file=%O;\n}\nSEGMENTS {\n  ZEROPAGE: load=ZP, type=zp;\n  CODE: load=RAM, type=ro;\n  RODATA: load=RAM, type=ro;\n  DATA: load=RAM, type=rw;\n  BSS: load=RAM, type=bss, define=yes;\n}\n",
  "src/hello.s": "; A routine the BASIC program calls with SYS 28672. It prints a line\n; through the kernel and returns to BASIC with RTS.\n.setcpu \"65C02\"\n.include \"clementina.inc\"       ; names the kernel's routines, like KERN_CHROUT\n.export hello\n\n.code\n\nhello:\n  ldx #0\n@next:\n  lda message,x                 ; the next character, or 0 at the end\n  beq @done\n  jsr KERN_CHROUT               ; print it\n  inx\n  bra @next\n@done:\n  rts                           ; back to BASIC\n\nmessage:\n  .byte \"HELLO FROM ASSEMBLY\", 13, 0\n",
